CREATE TABLE IF NOT EXISTS n5_bunpou_content_backup_176 (
 grammar_id UUID PRIMARY KEY, before_grammar JSONB NOT NULL,
 before_examples JSONB NOT NULL, after_grammar JSONB, after_examples JSONB
);
DO $complete$
DECLARE
 plan JSONB := $data$[{"bab":3,"lesson":"bunpou-n5-b3","pattern":"〜は〜です","notes":"Pola: A は B です. A adalah orang yang dibicarakan; B menyebut nama, asal, atau pekerjaan. は ditulis ha tetapi dibaca wa. です membuat kalimat sopan. Untuk memperkenalkan diri, tidak perlu menambahkan さん pada nama sendiri.","dialog":"A: はじめまして。わたしはアンナです。\nB: はじめまして。ハディです。","translation":"A: Salam kenal. Saya Anna.\nB: Salam kenal. Saya Hadi.","addExamples":[]},{"bab":3,"lesson":"bunpou-n5-b3","pattern":"〜は〜じゃ／ではありません","notes":"Pola: A は B じゃありません／ではありません. Artinya A bukan B. ではありません lebih formal; keduanya sopan. Bentuk ini dipakai dengan kata benda, misalnya がくせい. Jangan menghilangkan は ketika membandingkan identitas seseorang.","dialog":"A: がくせいですか。\nB: いいえ、がくせいじゃありません。せんせいです。","translation":"A: Apakah Anda pelajar?\nB: Bukan, saya bukan pelajar. Saya guru.","addExamples":[]},{"bab":3,"lesson":"bunpou-n5-b3","pattern":"〜ですか","notes":"Pola: A は B ですか. Tambahkan か setelah です untuk bertanya. Jawab はい jika benar dan いいえ jika tidak; lalu sebutkan identitas yang tepat. Dalam tulisan Jepang, 。 dapat dipakai di akhir pertanyaan ini.","dialog":"A: インドネシアじんですか。\nB: はい、インドネシアじんです。","translation":"A: Apakah Anda orang Indonesia?\nB: Ya, saya orang Indonesia.","addExamples":[]},{"bab":3,"lesson":"bunpou2-n5-b3","pattern":"〜の〜","notes":"Pola: A の B. Kata utama adalah B; A menerangkan pemilik atau afiliasinya. わたしのなまえ = nama saya; さくらだいがくのがくせい = mahasiswa Universitas Sakura. Jadi の tidak selalu berarti milik: universitas menerangkan tempat seseorang belajar.","dialog":"A: がくせいですか。\nB: はい、さくらだいがくのがくせいです。","translation":"A: Apakah Anda mahasiswa?\nB: Ya, saya mahasiswa Universitas Sakura.","addExamples":[]},{"bab":3,"lesson":"bunpou2-n5-b3","pattern":"〜も〜です","notes":"Pola: A も B です. Gunakan も ketika informasi yang sama berlaku bagi orang lain. も menggantikan は pada pola ini. Contoh membutuhkan konteks: setelah seseorang berkata bahwa ia pelajar, わたしもがくせいです berarti saya juga pelajar.","dialog":"A: わたしはがくせいです。\nB: わたしもがくせいです。","translation":"A: Saya pelajar.\nB: Saya juga pelajar.","addExamples":[]},{"bab":3,"lesson":"bunpou2-n5-b3","pattern":"〜文 + ね／よ","notes":"Tambahkan ね atau よ setelah kalimat lengkap. ね meminta persetujuan atau memastikan informasi yang diperkirakan sudah diketahui bersama. よ memberi informasi kepada lawan bicara. Keduanya bukan pengganti か untuk semua pertanyaan.","dialog":"A: がくせいですね。\nB: いいえ、せんせいですよ。","translation":"A: Anda pelajar, ya?\nB: Bukan, saya guru, lho.","addExamples":[]},{"bab":4,"lesson":"bunpou1-n5-b4","pattern":"これ／それ／あれは〜です","notes":"これ, それ, dan あれ berdiri sendiri sebagai kata ganti benda. これ: dekat pembicara; それ: dekat lawan bicara; あれ: jauh dari keduanya. Pola: これ／それ／あれ は kata benda です. Pilih berdasarkan posisi benda, bukan besar atau kecilnya.","dialog":"A: それはほんですか。\nB: はい、これはほんです。","translation":"A: Apakah itu buku?\nB: Ya, ini buku.","addExamples":[{"japanese":"あれはかばんです。","highlight":"あれ","indonesian":"Itu (jauh dari kita berdua) tas."}]},{"bab":4,"lesson":"bunpou1-n5-b4","pattern":"この／その／あの／どの + [Kata Benda]","notes":"この／その／あの／どの harus langsung diikuti kata benda: このほん, bukan このはほん. この dekat pembicara, その dekat lawan bicara, あの jauh dari keduanya. どの + kata benda menanyakan yang mana di antara pilihan. Untuk bertanya identitas pilihan, gunakan どのほんですか.","dialog":"A: どのほんですか。\nB: そのほんです。","translation":"A: Buku yang mana?\nB: Buku itu (di dekat Anda).","addExamples":[{"japanese":"どのほんですか。","highlight":"どの","indonesian":"Buku yang mana?"}],"replaceExamples":[["その本は日本のほんですか。","そのほんはにほんごのほんですか。","の","Apakah buku itu buku bahasa Jepang?"]]},{"bab":4,"lesson":"bunpou2-n5-b4","pattern":"〜の〜","notes":"Pola: A の B. B adalah benda utama; A menjelaskan jenis, bahasa, atau asalnya. にほんごのほん = buku bahasa Jepang; にほんのほん = buku dari Jepang. Jangan menyamakan にほん (Jepang) dengan にほんご (bahasa Jepang). Kepunyaan dengan の sudah dipelajari pada Bab 3.","dialog":"A: これはにほんごのほんですか。\nB: いいえ、インドネシアごのほんです。","translation":"A: Apakah ini buku bahasa Jepang?\nB: Bukan, ini buku bahasa Indonesia.","addExamples":[],"replaceDialog":true},{"bab":4,"lesson":"bunpou2-n5-b4","pattern":"そうです／ちがいます","notes":"Gunakan はい、そうです untuk membenarkan pernyataan dalam pertanyaan. Untuk menyangkal, gunakan いいえ、ちがいます dan tambahkan informasi yang benar. ちがいます juga bentuk sopan, bukan bentuk kasual. Untuk pertanyaan apa/yang mana, sebutkan jawabannya; そうです saja tidak menjawab pertanyaan itu.","dialog":"A: これはペンですか。\nB: いいえ、ちがいます。えんぴつです。\nA: それはノートですか。\nB: はい、そうです。","translation":"A: Apakah ini pena?\nB: Bukan. Ini pensil.\nA: Apakah itu buku tulis?\nB: Ya, benar.","addExamples":[],"replaceDialog":true,"meaning":"Membenarkan atau menyangkal dugaan lawan bicara.","replaceExamples":[["Q: この本は日本語の本ですか？ A: いいえ、ちがいます。インドネシア語の本です。","A: このほんはにほんごのほんですか。 B: いいえ、ちがいます。インドネシアごのほんです。","ちがいます","A: Apakah buku ini buku bahasa Jepang? B: Bukan, buku bahasa Indonesia."]]},{"bab":5,"lesson":"bunpou1-n5-b5","pattern":"いくら","notes":"Pola: benda は いくらですか. いくら menanyakan harga. Jawab dengan angka + えん (yen), misalnya ごひゃくえんです. Jika bendanya sudah jelas, cukup いくらですか. Jangan memakai なんさい karena itu menanyakan umur.","dialog":"A: このペンはいくらですか。\nB: ひゃくえんです。","translation":"A: Berapa harga pena ini?\nB: Seratus yen.","addExamples":[{"japanese":"このほんはいくらですか。","highlight":"いくら","indonesian":"Berapa harga buku ini?"},{"japanese":"そのほんはごひゃくえんです。","highlight":"ごひゃくえん","indonesian":"Buku itu harganya lima ratus yen."}]},{"bab":5,"lesson":"bunpou1-n5-b5","pattern":"今〜時〜分です","notes":"Pola: いま、angka + じ + angka + ふん／ぷん です. Pertanyaan: いま、なんじですか. Jam 4 = よじ, 7 = しちじ, 9 = くじ. Menit berubah bunyi: いっぷん, さんぷん, ろっぷん, はっぷん, じゅっぷん. はん berarti lewat setengah jam: さんじはん = 03.30.","dialog":"A: いま、なんじですか。\nB: さんじはんです。","translation":"A: Sekarang jam berapa?\nB: Jam setengah empat.","addExamples":[{"japanese":"いま、よじです。","highlight":"よじ","indonesian":"Sekarang pukul empat."},{"japanese":"いま、くじじゅっぷんです。","highlight":"くじじゅっぷん","indonesian":"Sekarang pukul sembilan lewat sepuluh menit."}],"replaceDialog":true},{"bab":5,"lesson":"bunpou2-n5-b5","pattern":"~から ~ まで","notes":"Pola: waktu awal から waktu akhir まで. から menunjukkan mulai/dari; まで menunjukkan sampai. Contoh: くじからごじまでです = dari pukul sembilan sampai pukul lima. Jangan tertukar dengan harga; harga ditanyakan dengan いくら.","dialog":"A: じゅぎょうはなんじからなんじまでですか。\nB: くじからじゅうじまでです。","translation":"A: Pelajarannya dari jam berapa sampai jam berapa?\nB: Dari pukul sembilan sampai pukul sepuluh.","addExamples":[{"japanese":"じゅぎょうはくじからじゅうじまでです。","highlight":"から","indonesian":"Pelajaran berlangsung dari pukul sembilan sampai pukul sepuluh."},{"japanese":"やすみはじゅうじからじゅうじはんまでです。","highlight":"まで","indonesian":"Istirahat berlangsung dari pukul sepuluh sampai pukul setengah sebelas."}],"replaceDialog":true},{"bab":5,"lesson":"bunpou2-n5-b5","pattern":"おいくつ/ 何さい","notes":"なんさいですか menanyakan umur. おいくつですか lebih halus. Jawaban: angka + さいです. Perhatikan いっさい (1), はっさい (8), じゅっさい (10), dan はたち (20). Tidak semua situasi perkenalan memerlukan pertanyaan umur; gunakan bila relevan.","dialog":"A: おいくつですか。\nB: はたちです。","translation":"A: Berapa usia Anda?\nB: Dua puluh tahun.","addExamples":[{"japanese":"なんさいですか。","highlight":"なんさい","indonesian":"Berapa umur Anda?"},{"japanese":"わたしははたちです。","highlight":"はたち","indonesian":"Saya berusia dua puluh tahun."}],"replaceDialog":true},{"bab":6,"lesson":"bunpou1-n5-b6","pattern":"〜は[い-adj]です","notes":"Pola: topik は kata sifat い です. Pertahankan い: あついです, bukan あつです atau あついだです. です membuat ucapan sopan. Pelajari kata sifat sebagai kata utuh: おいしい berarti enak, むずかしい berarti sulit.","dialog":"A: このおちゃはあついですか。\nB: はい、あついです。","translation":"A: Apakah teh ini panas?\nB: Ya, panas.","addExamples":[]},{"bab":6,"lesson":"bunpou1-n5-b6","pattern":"〜は[い-adj]くないです","notes":"Untuk bentuk negatif, ganti い terakhir dengan くないです: たかい → たかくないです. Pengecualian penting: いい → よくないです. Jangan memakai たかいじゃありません. Rumus ini untuk kata sifat い; kata sifat な dibahas pada Bab 7.","dialog":"A: このほんはたかいですか。\nB: いいえ、たかくないです。","translation":"A: Apakah buku ini mahal?\nB: Tidak, tidak mahal.","addExamples":[{"japanese":"きょうのてんきはよくないです。","highlight":"よくないです","indonesian":"Cuaca hari ini tidak baik."}],"meaning":"Menyatakan sifat yang tidak berlaku (bentuk negatif)."},{"bab":6,"lesson":"bunpou1-n5-b6","pattern":"〜かったです","notes":"Untuk menceritakan sifat pada masa lalu, ganti い terakhir dengan かったです: あつい → あつかったです. いい berubah menjadi よかったです. Gunakan penanda waktu yang jelas, misalnya きのう. Jangan memakai あついでした.","dialog":"A: きのうはあつかったですか。\nB: はい、とてもあつかったです。","translation":"A: Apakah kemarin panas?\nB: Ya, sangat panas.","addExamples":[],"replaceExamples":[["きのう、たべもの、とてもおいしかったです。","きのうのりょうりはとてもおいしかったです。","おいしかったです","Masakan kemarin sangat enak."]]},{"bab":6,"lesson":"bunpou1-n5-b6","pattern":"〜くなかったです","notes":"Bentuk negatif lampau: buang い terakhir dari kata sifat, lalu tambah くなかったです. おいしい → おいしくなかったです. いい → よくなかったです. Bedakan くないです (tidak) dengan くなかったです (waktu itu tidak).","dialog":"A: きのうはいそがしかったですか。\nB: いいえ、いそがしくなかったです。","translation":"A: Apakah kemarin Anda sibuk?\nB: Tidak, kemarin saya tidak sibuk.","addExamples":[],"replaceExamples":[["きょうの天気はよくなかったです。","きのうのてんきはよくなかったです。","よくなかったです","Cuaca kemarin tidak bagus."],["このケーキはおいしくなかったです。","このケーキはおいしくなかったです。","おいしくなかったです","Kue ini tadi tidak enak."]]},{"bab":6,"lesson":"bunpou2-n5-b6","pattern":"[い-adj]+ noun","notes":"Pola: kata sifat い + kata benda. い tetap ada dan tidak disisipi な atau の: あたらしいほん = buku baru. Untuk membuat kalimat sopan, tambahkan です setelah kata bendanya: あたらしいほんです.","dialog":"A: このほんはあたらしいほんですか。\nB: はい、あたらしいほんです。","translation":"A: Apakah buku ini buku baru?\nB: Ya, buku baru.","addExamples":[],"replaceExamples":[["新（あたら）しい店（みせ）です。","あたらしいみせです。","あたらしい","Ini toko baru."],["Rendangは美味（おい）しいたべものです。","レンダンはおいしいたべものです。","おいしい","Rendang adalah makanan yang enak."]]},{"bab":6,"lesson":"bunpou2-n5-b6","pattern":"とても","notes":"とても berarti sangat. Letakkan sebelum kata sifat yang diterangkan: とてもあついです. とても bukan akhiran kata sifat dan tidak menggantikan です. Pada bab ini gunakan untuk menyatakan tingkat sifat, bukan seberapa sering kegiatan dilakukan.","dialog":"A: このケーキはどうですか。\nB: とてもおいしいです。","translation":"A: Bagaimana kue ini?\nB: Sangat enak.","addExamples":[]},{"bab":6,"lesson":"bunpou2-n5-b6","pattern":"あまり〜","notes":"Pada pola dasar ini, あまり + bentuk negatif berarti tidak terlalu. あまりたかくないです = tidak terlalu mahal. Untuk lampau: あまりたかくなかったです. Bedakan dengan とてもたかいです = sangat mahal. Contoh bab ini cukup memakai sifat; penghubung sebab dipelajari kemudian.","dialog":"A: このりょうりはからいですか。\nB: いいえ、あまりからくないです。","translation":"A: Apakah masakan ini pedas?\nB: Tidak, tidak terlalu pedas.","addExamples":[],"meaning":"Menyatakan tingkat sifat yang tidak terlalu tinggi.","replaceExamples":[["この映画はあまり面白くないから、途中で寝てしまいました。","このえいがはあまりおもしろくないです。","おもしろくないです","Film ini tidak terlalu menarik."]]},{"bab":6,"lesson":"bunpou2-n5-b6","pattern":"〜はどうですか","notes":"Pola: topik は どうですか. Gunakan untuk meminta pendapat atau kesan; jawab dengan sifat yang sesuai. どうでしたか menanyakan kesan tentang sesuatu yang sudah berlalu. どうですか bukan pertanyaan ya/tidak, jadi はい saja tidak cukup.","dialog":"A: このりょうりはどうですか。\nB: おいしいです。あまりからくないです。","translation":"A: Bagaimana masakan ini?\nB: Enak. Tidak terlalu pedas.","addExamples":[],"replaceDialog":true},{"bab":7,"lesson":"bunpou1-n5-b7","pattern":"〜は[Kata Sifat な]です","notes":"Pola: topik は kata sifat な tanpa な + です. しずかです = tenang; jangan menulis しずかなです. きれい dan きらい termasuk kata sifat な walaupun berakhir bunyi い. Bedakan dengan kata sifat い seperti あたらしい.","dialog":"A: このへやはしずかですか。\nB: はい、しずかです。","translation":"A: Apakah ruangan ini tenang?\nB: Ya, tenang.","addExamples":[{"japanese":"このへやはしずかです。","highlight":"しずかです","indonesian":"Ruangan ini tenang."}],"translateExamples":[["この部屋はきれいです。","Ruangan ini bersih."]]},{"bab":7,"lesson":"bunpou1-n5-b7","pattern":"Kata Sifat な＋Kata Benda","notes":"Pola: kata sifat な + な + kata benda. な diperlukan sebelum kata benda: しずかなへや = ruangan yang tenang. Bandingkan へやはしずかです dengan しずかなへやです. Jangan menggunakan の untuk menyambungkan kata sifat な dengan kata bendanya.","dialog":"A: これはしずかなへやですか。\nB: はい、しずかなへやです。","translation":"A: Apakah ini ruangan yang tenang?\nB: Ya, ruangan yang tenang.","addExamples":[{"japanese":"きれいなまちです。","highlight":"きれいな","indonesian":"Kota yang indah."},{"japanese":"しずかなへやです。","highlight":"しずかな","indonesian":"Ruangan yang tenang."}]},{"bab":7,"lesson":"bunpou1-n5-b7","pattern":"〜は[Kata Sifat な]じゃありません。","notes":"Pola negatif: kata sifat な tanpa な + じゃありません／ではありません. しずかじゃありません = tidak tenang. Jangan mengubahnya menjadi しずかくない. Jika sifat menerangkan kata benda, pertahankan な: しずかなへやじゃありません = bukan ruangan yang tenang.","dialog":"A: このまちはしずかですか。\nB: いいえ、しずかじゃありません。","translation":"A: Apakah kota ini tenang?\nB: Tidak, tidak tenang.","addExamples":[{"japanese":"このへやはしずかじゃありません。","highlight":"じゃありません","indonesian":"Ruangan ini tidak tenang."},{"japanese":"あのまちはにぎやかではありません。","highlight":"ではありません","indonesian":"Kota itu tidak ramai."}]},{"bab":7,"lesson":"bunpou2-n5-b7","pattern":"Hal +が　好き/嫌い/上手/下手","notes":"Pola: orang は hal が すき／きらい／じょうず／へた です. すき = suka, きらい = tidak suka, じょうず = mahir, へた = kurang mahir. Kesukaan berbeda dari kemampuan: suka menyanyi belum tentu mahir. Gunakan が sebelum sifat-sifat ini; jangan menggantinya dengan を.","dialog":"A: うたがすきですか。\nB: はい、すきです。\nA: うたがじょうずですか。\nB: いいえ、あまりじょうずじゃありません。","translation":"A: Apakah Anda suka menyanyi?\nB: Ya, suka.\nA: Apakah Anda mahir menyanyi?\nB: Tidak, saya tidak terlalu mahir.","addExamples":[{"japanese":"わたしはねこがすきです。","highlight":"がすきです","indonesian":"Saya suka kucing."},{"japanese":"わたしはさかながきらいです。","highlight":"がきらいです","indonesian":"Saya tidak suka ikan."},{"japanese":"たなかさんはうたがじょうずです。","highlight":"がじょうずです","indonesian":"Tanaka mahir menyanyi."},{"japanese":"わたしはりょうりがへたです。","highlight":"がへたです","indonesian":"Saya kurang mahir memasak."}],"meaning":"Menyatakan kesukaan atau tingkat kemahiran."},{"bab":7,"lesson":"bunpou2-n5-b7","pattern":"〜で〜くて","notes":"Untuk menggabungkan sifat: kata sifat い → buang い + くて; kata sifat な → dasar + で. おいしくてやすいです = enak dan murah; しずかできれいです = tenang dan indah. Kata benda juga memakai で: がくせいで、はたちです. いい berubah menjadi よくて.","dialog":"A: このへやはどうですか。\nB: しずかできれいです。","translation":"A: Bagaimana ruangan ini?\nB: Tenang dan bersih.","addExamples":[],"meaning":"Menghubungkan sifat atau keterangan kata benda.","replaceExamples":[["この店は安くて美味しいです。","このりょうりはやすくておいしいです。","やすくて","Masakan ini murah dan enak."],["Soloはしずかできれいな町（まち）です。","ソロはしずかできれいなまちです。","しずかで","Solo adalah kota yang tenang dan indah."]],"translationReplacements":[["A: Kopinya di sini juga enak.","A: Saya juga suka kopi di sini."]]},{"bab":7,"lesson":"bunpou2-n5-b7","pattern":"Kata Sifat な＋でした/じゃありませんでした","notes":"Kata sifat な tanpa な + でした menyatakan sifat pada masa lalu. Negatifnya: じゃありませんでした. Contoh: しずかでした／しずかじゃありませんでした. Pola yang sama berlaku untuk kata benda. Kata sifat い tetap memakai かったです, bukan でした.","dialog":"A: きのうはひまでしたか。\nB: いいえ、ひまじゃありませんでした。","translation":"A: Apakah kemarin Anda senggang?\nB: Tidak, kemarin saya tidak senggang.","addExamples":[{"japanese":"きのうはひまでした。","highlight":"ひまでした","indonesian":"Kemarin saya senggang."},{"japanese":"きのうのへやはしずかじゃありませんでした。","highlight":"じゃありませんでした","indonesian":"Ruangan kemarin tidak tenang."}]},{"bab":8,"lesson":"bunpou1-n5-b8","pattern":"〜に〜があります／います","notes":"Pola: tempat に benda/orang が あります／います. に menandai tempat; が memperkenalkan yang ada di situ. Gunakan います untuk manusia/hewan dan あります untuk benda serta tumbuhan. Kalimat ini menjawab apa/siapa yang ada di tempat itu.","dialog":"A: きょうしつにせんせいがいますか。\nB: はい、います。","translation":"A: Apakah ada guru di kelas?\nB: Ya, ada.","addExamples":[],"dialogReplacements":[["いますか。。","いますか。"]]},{"bab":8,"lesson":"bunpou1-n5-b8","pattern":"〜は〜にあります／います","notes":"Pola: benda/orang は tempat に あります／います. Yang dicari sudah menjadi topik, lalu kita menjelaskan lokasinya. ほんはへやにあります menjawab bukunya di mana. Gunakan います untuk manusia/hewan, あります untuk benda/tumbuhan.","dialog":"A: せんせいはどこにいますか。\nB: きょうしつにいます。","translation":"A: Guru ada di mana?\nB: Di kelas.","addExamples":[]},{"bab":8,"lesson":"bunpou1-n5-b8","pattern":"ここ/そこ/あそこ","notes":"ここ = tempat dekat pembicara; そこ = tempat dekat lawan bicara; あそこ = tempat jauh dari keduanya. Jika keduanya berdiri bersama, そこ dapat menunjuk tempat agak jauh dan あそこ tempat lebih jauh. Gunakan は untuk menjelaskan tempat atau に sebelum あります／います.","dialog":"A: としょかんはどこですか。\nB: あそこです。","translation":"A: Perpustakaan di mana?\nB: Di sana.","addExamples":[{"japanese":"あそこはぎんこうです。","highlight":"あそこ","indonesian":"Tempat di sana adalah bank."}],"replaceDialog":true},{"bab":8,"lesson":"bunpou1-n5-b8","pattern":"こちら/そちら/あちら","notes":"こちら／そちら／あちら adalah ungkapan sopan untuk tempat atau arah: sebelah sini/situ/sana. どちら menanyakan arah atau tempat dengan sopan. こちら juga bisa dipakai saat memperkenalkan seseorang; pada bab ini fokuskan pemakaiannya untuk lokasi.","dialog":"A: トイレはどちらですか。\nB: あちらです。","translation":"A: Toilet ada di sebelah mana?\nB: Di sebelah sana.","addExamples":[{"japanese":"うけつけはこちらです。","highlight":"こちら","indonesian":"Resepsionis ada di sebelah sini."},{"japanese":"エレベーターはそちらです。","highlight":"そちら","indonesian":"Lift ada di sebelah situ."}],"replaceDialog":true},{"bab":8,"lesson":"bunpou1-n5-b8","pattern":"Kata Benda はTempat です","notes":"Pola singkat untuk menyebut lokasi: topik は tempat です. トイレはにかいです = toilet di lantai dua. Dalam konteks lokasi, です di sini dipahami sebagai berada di. Bentuk yang lebih lengkap memakai tempat にあります／います; jangan menambahkan に tepat sebelum です.","dialog":"A: トイレはどこですか。\nB: にかいです。","translation":"A: Toilet di mana?\nB: Di lantai dua.","addExamples":[{"japanese":"トイレはにかいです。","highlight":"にかいです","indonesian":"Toilet ada di lantai dua."}],"meaning":"Menyatakan lokasi dengan kalimat singkat."},{"bab":8,"lesson":"bunpou2-n5-b8","pattern":"どこに〜がありますか","notes":"どこ menanyakan tempat. どこにほんがありますか menanyakan di mana ada buku. Jika buku tertentu sudah menjadi topik, gunakan ほんはどこにありますか. Untuk mencari seseorang, ganti あります dengan います. Jawab dengan tempat + にあります／います.","dialog":"A: どこにほんがありますか。\nB: あのへやにあります。","translation":"A: Di mana ada buku?\nB: Ada di ruangan itu.","addExamples":[{"japanese":"どこにぎんこうがありますか。","highlight":"どこに","indonesian":"Di mana ada bank?"}]},{"bab":8,"lesson":"bunpou2-n5-b8","pattern":"どこ/どちら","notes":"どこですか menanyakan tempat; どちらですか lebih sopan. Keduanya dapat dijawab dengan lokasi: にかいです, あそこです. Pada pelajaran ini どちら dipakai untuk lokasi. Pemakaian どちら untuk membandingkan dua pilihan dipelajari pada Bab 18.","dialog":"A: うけつけはどちらですか。\nB: こちらです。","translation":"A: Resepsionis ada di mana?\nB: Di sebelah sini.","addExamples":[]},{"bab":8,"lesson":"bunpou2-n5-b8","pattern":"Kata benda 1( benda/orang tempat) の Kata benda 2 (posisi)","notes":"Pola: benda patokan の posisi. つくえのうえ = di atas meja, した = bawah, まえ = depan, うしろ = belakang, となり = sebelah. Tambahkan に untuk lokasi keberadaan. Untuk di antara A dan B: A と B のあいだ. Pastikan terjemahan tetap menyebut benda/orang yang sama.","dialog":"A: かばんはどこにありますか。\nB: つくえのしたにあります。","translation":"A: Tas ada di mana?\nB: Di bawah meja.","addExamples":[{"japanese":"ねこはつくえのしたにいます。","highlight":"のした","indonesian":"Kucing ada di bawah meja."},{"japanese":"ぎんこうはえきのまえにあります。","highlight":"のまえ","indonesian":"Bank ada di depan stasiun."},{"japanese":"くるまはいえのうしろにあります。","highlight":"のうしろ","indonesian":"Mobil ada di belakang rumah."}],"replaceDialog":true,"replaceExamples":[["ぎんこうは学校とスーパーのあいだにあります。","ぎんこうはがっこうとスーパーのあいだにあります。","のあいだ","Bank berada di antara sekolah dan supermarket."]]},{"bab":9,"lesson":"bunpou1-n5-b9","pattern":"〜へ行きます／来ます／帰ります","notes":"Pola: tujuan へ いきます／きます／かえります. へ dibaca e. いきます = pergi ke tempat lain; きます = datang ke tempat pembicara atau titik acuan percakapan; かえります = pulang. Ketiganya tidak dapat saling diganti tanpa mengubah sudut pandang.","dialog":"A: あした、ここへきますか。\nB: はい、きます。","translation":"A: Apakah besok Anda datang ke sini?\nB: Ya, saya akan datang.","addExamples":[{"japanese":"ともだちはあしたここへきます。","highlight":"きます","indonesian":"Teman saya besok datang ke sini."}],"replaceDialog":true},{"bab":9,"lesson":"bunpou1-n5-b9","pattern":"Kendaraan で　へ行きます／来ます／帰ります","notes":"Pola: kendaraan で tujuan へ kata kerja perjalanan. で menunjukkan kendaraan, へ menunjukkan tujuan. バスでがっこうへいきます = pergi ke sekolah naik bus. Untuk berjalan kaki gunakan あるいていきます, bukan あるいてでいきます. Hindari mencampur いきます dan きます tanpa titik acuan yang jelas.","dialog":"A: がっこうへバスでいきますか。\nB: いいえ、でんしゃでいきます。","translation":"A: Apakah Anda pergi ke sekolah naik bus?\nB: Tidak, saya naik kereta.","addExamples":[],"replaceDialog":true},{"bab":9,"lesson":"bunpou1-n5-b9","pattern":"〜で行きます","notes":"Jika tujuan sudah jelas, kendaraan でいきます cukup untuk menjelaskan cara pergi. でんしゃで = naik kereta; バスで = naik bus. Pola ini adalah latihan lanjutan penggunaan で dari kartu sebelumnya. Berjalan kaki memakai あるいて, tanpa で.","dialog":"A: えきへバスでいきますか。\nB: いいえ、あるいていきます。","translation":"A: Apakah Anda pergi ke stasiun naik bus?\nB: Tidak, saya berjalan kaki.","addExamples":[]},{"bab":9,"lesson":"bunpou2-n5-b9","pattern":"〜から〜まで","notes":"Pola rute: tempat awal から tempat tujuan まで kata kerja. から = dari; まで = sampai. Bandingkan Bab 5 yang memakai dua waktu. Kedua batas harus sejenis: tempat dengan tempat untuk rute, waktu dengan waktu untuk rentang waktu.","dialog":"A: うちからえきまでバスでいきますか。\nB: はい、バスでいきます。","translation":"A: Apakah Anda pergi dari rumah sampai stasiun naik bus?\nB: Ya, naik bus.","addExamples":[]},{"bab":9,"lesson":"bunpou2-n5-b9","pattern":"いつ／どこへ／だれと","notes":"いつ menanyakan kapan dan biasanya tanpa に. どこへ menanyakan tujuan. だれと menanyakan teman perjalanan; と berarti bersama. Jawab masing-masing dengan waktu, tempat, atau orang. Jawaban ひとりで berarti sendirian dan tidak memakai と.","dialog":"A: あした、どこへいきますか。\nB: とうきょうへいきます。\nA: だれといきますか。\nB: ともだちといきます。","translation":"A: Besok Anda pergi ke mana?\nB: Saya pergi ke Tokyo.\nA: Pergi bersama siapa?\nB: Bersama teman.","addExamples":[{"japanese":"いつにほんへいきますか。","highlight":"いつ","indonesian":"Kapan Anda pergi ke Jepang?"}]},{"bab":10,"lesson":"bunpou1-n5-b10","pattern":"〜を[verb]ます","notes":"Pola: objek を kata kerja bentuk ます. を dibaca o dan menandai objek tindakan: ほんをよみます. ます dapat menyatakan kebiasaan atau kegiatan yang akan dilakukan; bukan berarti selalu sedang. Tujuan perjalanan tetap memakai へ／に, bukan を pada pola dasar ini.","dialog":"A: まいあさ、なにをのみますか。\nB: コーヒーをのみます。","translation":"A: Apa yang Anda minum setiap pagi?\nB: Saya minum kopi.","addExamples":[]},{"bab":10,"lesson":"bunpou1-n5-b10","pattern":"[verb]ません","notes":"Ganti ます dengan ません: のみます → のみません. Bentuk sopan ini menyatakan tidak melakukan kegiatan sebagai kebiasaan atau rencana. Untuk kegiatan yang tidak dilakukan pada masa lalu, gunakan ませんでした.","dialog":"A: コーヒーをのみますか。\nB: いいえ、のみません。","translation":"A: Apakah Anda minum kopi?\nB: Tidak, saya tidak minum kopi.","addExamples":[]},{"bab":10,"lesson":"bunpou1-n5-b10","pattern":"[verb]ました","notes":"Ganti ます dengan ました untuk kegiatan yang terjadi pada masa lalu: よみます → よみました. Penanda seperti きのう atau けさ membantu memperjelas waktu. Jangan menambahkan でした setelah ます.","dialog":"A: きのう、ほんをよみましたか。\nB: はい、よみました。","translation":"A: Apakah kemarin Anda membaca buku?\nB: Ya, saya membaca buku.","addExamples":[]},{"bab":10,"lesson":"bunpou1-n5-b10","pattern":"[verb]ませんでした","notes":"Ganti ます dengan ませんでした untuk kegiatan yang tidak dilakukan pada masa lalu. きのう、べんきょうしませんでした = kemarin tidak belajar. Bedakan dengan べんきょうしません yang menyatakan kebiasaan atau rencana tidak belajar.","dialog":"A: きのう、テレビをみましたか。\nB: いいえ、みませんでした。","translation":"A: Apakah kemarin Anda menonton televisi?\nB: Tidak, kemarin saya tidak menonton televisi.","addExamples":[]},{"bab":10,"lesson":"bunpou2-n5-b10","pattern":"毎日／いつも／時々","notes":"まいにち = setiap hari; いつも = selalu/biasanya secara konsisten; ときどき = kadang-kadang. Letakkan sebelum kegiatan. まいにち menyebut siklus hari, sedangkan いつも tidak menentukan satuan waktu. Kata-kata ini tidak memakai に.","dialog":"A: まいにち、ほんをよみますか。\nB: いいえ、ときどきよみます。","translation":"A: Apakah Anda membaca buku setiap hari?\nB: Tidak, saya kadang-kadang membaca.","addExamples":[{"japanese":"いつもあさごはんをたべます。","highlight":"いつも","indonesian":"Saya selalu sarapan."}]},{"bab":10,"lesson":"bunpou2-n5-b10","pattern":"よく／ぜんぜん","notes":"よく + kata kerja berarti sering. ぜんぜん + bentuk negatif berarti sama sekali tidak, misalnya ぜんぜんみません. Bedakan dengan あまり + negatif yang berarti tidak terlalu sering. Untuk makna dasar yang dipelajari di sini, jangan memasangkan ぜんぜん dengan bentuk positif.","dialog":"A: よくテレビをみますか。\nB: いいえ、ぜんぜんみません。","translation":"A: Apakah Anda sering menonton televisi?\nB: Tidak, saya sama sekali tidak menonton televisi.","addExamples":[]},{"bab":11,"lesson":"bunpou1-n5-b11","pattern":"〜を[counter]+[verb]","notes":"Pola: benda を jumlah + kata bantu bilangan + kata kerja. Contoh: ほんをにさつかいます = membeli dua buku. Pilih kata bantu sesuai benda: さつ untuk buku, まい untuk benda tipis, ほん untuk benda panjang. Jangan menaruh を lagi setelah jumlah.","dialog":"A: ほんをなんさつかいますか。\nB: にさつかいます。","translation":"A: Berapa buku yang Anda beli?\nB: Saya membeli dua buku.","addExamples":[{"japanese":"ほんをにさつかいます。","highlight":"にさつ","indonesian":"Saya membeli dua buku."},{"japanese":"みずをさんぼんかいます。","highlight":"さんぼん","indonesian":"Saya membeli tiga botol air."}],"meaning":"Menyebut jumlah objek dalam kegiatan."},{"bab":11,"lesson":"bunpou1-n5-b11","pattern":"[counter]+ あります／います","notes":"Pola: benda/orang が jumlah あります／います. ほんがさんさつあります = ada tiga buku. Untuk orang gunakan にん dengan います; satu dan dua orang adalah ひとり dan ふたり. Jumlah tidak mengubah pemilihan あります versus います.","dialog":"A: きょうしつにがくせいがなんにんいますか。\nB: さんにんいます。","translation":"A: Ada berapa siswa di kelas?\nB: Ada tiga orang.","addExamples":[],"meaning":"Menyebut jumlah benda atau orang yang ada."},{"bab":11,"lesson":"bunpou2-n5-b11","pattern":"いくつ／何人／何枚","notes":"いくつ menanyakan jumlah benda dengan hitungan umum; なんにん menanyakan orang; なんまい menanyakan lembar/benda tipis. Jawaban harus memakai satuan yang cocok: ふたり, さんまい. いくつ juga dapat menanyakan umur pada konteks lain, tetapi di kartu ini dipakai untuk jumlah benda.","dialog":"A: きってはなんまいありますか。\nB: さんまいあります。","translation":"A: Ada berapa lembar perangko?\nB: Ada tiga lembar.","addExamples":[{"japanese":"きってはなんまいありますか。","highlight":"なんまい","indonesian":"Ada berapa lembar perangko?"}]},{"bab":11,"lesson":"bunpou2-n5-b11","pattern":"Native counters","notes":"Hitungan umum 1–10: ひとつ、ふたつ、みっつ、よっつ、いつつ、むっつ、ななつ、やっつ、ここのつ、とお. Bentuk 10 tidak berakhir つ. Gunakan untuk benda yang dapat dihitung secara umum, bukan pengganti semua satuan; orang memakai ひとり／ふたり／〜にん.","dialog":"A: りんごはいくつありますか。\nB: よっつあります。","translation":"A: Ada berapa buah apel?\nB: Ada empat buah.","addExamples":[{"japanese":"りんごがとおあります。","highlight":"とお","indonesian":"Ada sepuluh buah apel."}],"meaning":"Menghitung benda secara umum dari satu sampai sepuluh."},{"bab":12,"lesson":"tata-bahasa-bab-12-konjugasi-te-form","pattern":"Te-form Golongan 1 (u-verbs)","notes":"Mulai dari bentuk kamus. Golongan 1: う・つ・る → って; む・ぶ・ぬ → んで; く → いて; ぐ → いで; す → して. Contoh: かう→かって、のむ→のんで、かく→かいて、およぐ→およいで、はなす→はなして. Pengecualian: いく→いって. Perubahan mengikuti golongan kata, bukan hanya satu huruf terakhir.","dialog":"A: あした、なにをしますか。\nB: ほんをよんで、てがみをかきます。","translation":"A: Besok Anda melakukan apa?\nB: Saya membaca buku, lalu menulis surat.","addExamples":[]},{"bab":12,"lesson":"tata-bahasa-bab-12-konjugasi-te-form","pattern":"Te-form Golongan 2 (ru-verbs)","notes":"Untuk golongan 2, buang る dari bentuk kamus dan tambah て: たべる→たべて、みる→みて、おきる→おきて. Tidak semua kata berakhiran いる／える termasuk golongan 2: かえる (pulang) dan はいる (masuk) adalah golongan 1. Pelajari golongan bersama kosakatanya.","dialog":"A: きょうのよる、なにをしますか。\nB: ごはんをたべて、テレビをみます。","translation":"A: Malam ini Anda melakukan apa?\nB: Saya makan, lalu menonton televisi.","addExamples":[]},{"bab":12,"lesson":"tata-bahasa-bab-12-konjugasi-te-form","pattern":"Te-form Tidak Beraturan","notes":"Dua kata kerja golongan 3: する→して dan くる→きて. Gabungan dengan する mengikuti pola yang sama: べんきょうする→べんきょうして. Bentuk て tidak menentukan waktu sendirian; akhir kalimat menentukan apakah kegiatannya kini, mendatang, atau lampau.","dialog":"A: きのう、なにをしましたか。\nB: べんきょうして、ほんをよみました。","translation":"A: Kemarin Anda melakukan apa?\nB: Saya belajar, lalu membaca buku.","addExamples":[{"japanese":"ともだちはうちへきて、ごはんをたべました。","highlight":"きて","indonesian":"Teman saya datang ke rumah, lalu makan."}],"replaceExamples":[["学校から かえって きて、ごはんを 食べます。","ともだちはうちへきて、ごはんをたべました。","きて","Teman saya datang ke rumah, lalu makan."]]},{"bab":12,"lesson":"tata-bahasa-bab-12-menghubungkan-kalimat-te-form","pattern":"〜て、〜","notes":"Untuk urutan kegiatan, pakai bentuk て pada kata kerja sebelum yang terakhir: あさごはんをたべて、がっこうへいきます. Waktu dan kesopanan dinyatakan oleh kata kerja terakhir. Bentuk て juga memiliki fungsi lain; pelajaran ini fokus pada rangkaian tindakan.","dialog":"A: けさ、なにをしましたか。\nB: あさごはんをたべて、がっこうへいきました。","translation":"A: Tadi pagi Anda melakukan apa?\nB: Saya sarapan, lalu pergi ke sekolah.","addExamples":[]},{"bab":12,"lesson":"tata-bahasa-bab-12-menghubungkan-kalimat-te-form","pattern":"〜てから","notes":"Pola: Vてから、kegiatan berikutnya. Artinya setelah kegiatan pertama, barulah kegiatan kedua. Dibanding rangkaian て yang biasa, てから menonjolkan urutan atau prasyarat. Jangan menambah から setelah bentuk ます untuk makna setelah melakukan.","dialog":"A: しゅくだいをしてから、テレビをみますか。\nB: はい、しゅくだいをしてから、みます。","translation":"A: Apakah Anda menonton televisi setelah mengerjakan PR?\nB: Ya, saya menonton setelah mengerjakan PR.","addExamples":[]},{"bab":13,"lesson":"tata-bahasa-bab-13-progresif-permintaan","pattern":"〜てください","notes":"Pola: kata kerja bentuk て + ください. Dipakai untuk meminta tindakan atau memberi instruksi: かいてください = tolong tulis. Walaupun sopan, bentuk ini dapat terdengar langsung; sesuaikan dengan hubungan dan situasi. Jangan mengganti て dengan bentuk kamus.","dialog":"A: ここになまえをかいてください。\nB: はい、わかりました。","translation":"A: Tolong tulis nama di sini.\nB: Baik, saya mengerti.","addExamples":[]},{"bab":13,"lesson":"tata-bahasa-bab-13-progresif-permintaan","pattern":"〜てくれませんか","notes":"Pola: Vて + くれませんか. Meminta bantuan dengan menanyakan kesediaan lawan bicara: よんでくれませんか = bisa tolong bacakan? Bukan pertanyaan apakah seseorang tidak melakukan kegiatan. Bentuk ini tidak otomatis cocok untuk semua atasan atau situasi sangat resmi.","dialog":"A: すみません、このかんじをよんでくれませんか。\nB: はい。「やま」です。","translation":"A: Permisi, bisa tolong bacakan kanji ini?\nB: Ya. Bunyinya yama.","addExamples":[]},{"bab":13,"lesson":"tata-bahasa-bab-13-progresif-permintaan","pattern":"〜ています","notes":"Pola: Vて + います. Maknanya bergantung pada kata dan konteks: いまよんでいます = sedang membaca; すんでいます = tinggal; けっこんしています = sudah menikah; まいあさはしっています = rutin berlari setiap pagi. Jangan menerjemahkan semuanya sebagai sedang.","dialog":"A: いま、なにをしていますか。\nB: ほんをよんでいます。","translation":"A: Sekarang Anda sedang melakukan apa?\nB: Saya sedang membaca buku.","addExamples":[{"japanese":"あにはけっこんしています。","highlight":"けっこんしています","indonesian":"Kakak laki-laki saya sudah menikah."}]},{"bab":13,"lesson":"tata-bahasa-bab-13-izin-larangan","pattern":"〜てもいいですか","notes":"Pola: Vて + もいいですか untuk meminta izin. Jawaban izin: はい、いいですよ. Gunakan untuk tindakan pembicara sendiri. Bedakan よんでもいいですか (boleh saya membaca?) dengan よんでください (tolong Anda baca).","dialog":"A: このほんをよんでもいいですか。\nB: はい、いいですよ。","translation":"A: Bolehkah saya membaca buku ini?\nB: Ya, boleh.","addExamples":[]},{"bab":13,"lesson":"tata-bahasa-bab-13-izin-larangan","pattern":"〜てはいけません","notes":"Pola: Vて + はいけません. Menyatakan larangan atau aturan, bukan sekadar tidak suka. Bentuk て yang berakhir で tetap dipertahankan: あそんではいけません. Bedakan larangan ini dari てもいいです yang memberi izin.","dialog":"A: ここでしゃしんをとってもいいですか。\nB: いいえ、ここではとってはいけません。","translation":"A: Bolehkah saya memotret di sini?\nB: Tidak, di sini tidak boleh memotret.","addExamples":[]},{"bab":14,"lesson":"tata-bahasa-bab-14-bentuk-nai-kewajiban","pattern":"[V-jisho] (Bentuk Kamus)","notes":"Bentuk kamus adalah bentuk dasar yang ditemukan dalam kamus. Dari bentuk ます: golongan 1 ubah bunyi i sebelum ます menjadi u (のみます→のむ); golongan 2 ganti ます dengan る (たべます→たべる); します→する、きます→くる. Dalam kalimat mandiri bentuk ini biasa digunakan dengan teman dekat, bukan otomatis sopan.","dialog":"A: あした、なにをする？\nB: ほんをよむ。","translation":"A: Besok mau melakukan apa? (percakapan akrab)\nB: Membaca buku.","addExamples":[]},{"bab":14,"lesson":"tata-bahasa-bab-14-bentuk-nai-kewajiban","pattern":"Nai-form (konjugasi)","notes":"Dari bentuk kamus: golongan 1, bunyi u→a + ない (のむ→のまない); akhiran う menjadi わない (かう→かわない). Golongan 2: る→ない. Golongan 3: する→しない、くる→こない. Pengecualian: ある→ない. Ini bentuk negatif biasa; versi sopannya ません.","dialog":"A: あした、がっこうへいく？\nB: ううん、いかない。","translation":"A: Besok pergi ke sekolah? (percakapan akrab)\nB: Tidak, aku tidak pergi.","addExamples":[],"replaceExamples":[["あさごはんを 食べない 人も います。","あしたはあさごはんをたべない。","たべない","Besok saya tidak sarapan."]]},{"bab":14,"lesson":"tata-bahasa-bab-14-bentuk-nai-kewajiban","pattern":"[V-ta] (Lampau Plain)","notes":"Bentuk lampau biasa dibuat dari bentuk て: ganti て→た atau で→だ. かいて→かいた、のんで→のんだ、たべて→たべた、して→した、きて→きた. いく menjadi いった. Dalam percakapan sopan, bentuk lampau mandiri memakai ました.","dialog":"A: きのう、ほんをよんだ？\nB: うん、よんだ。","translation":"A: Kemarin membaca buku? (percakapan akrab)\nB: Ya, aku membaca buku.","addExamples":[]},{"bab":14,"lesson":"tata-bahasa-bab-14-bentuk-nai-kewajiban","pattern":"[V-nakatta]","notes":"Mulai dari bentuk ない, lalu ganti ない dengan なかった: のまない→のまなかった、たべない→たべなかった. Ini berarti tidak melakukan pada masa lalu. Bedakan dengan ない (tidak/belum dalam konteks kini atau mendatang). Versi sopannya ませんでした.","dialog":"A: きのう、テレビをみた？\nB: ううん、みなかった。","translation":"A: Kemarin menonton televisi? (percakapan akrab)\nB: Tidak, aku tidak menonton.","addExamples":[]},{"bab":14,"lesson":"tata-bahasa-bab-14-bentuk-plain","pattern":"〜ないでください","notes":"Pola: bentuk ない UTUH + でください. い pada ない tidak dibuang: はいる→はいらない→はいらないでください. Artinya tolong jangan melakukan. Jangan tertukar dengan なくて atau mengubahnya menjadi はいらなでください.","dialog":"A: このへやにはいらないでください。\nB: はい、わかりました。","translation":"A: Tolong jangan masuk ke ruangan ini.\nB: Baik, saya mengerti.","addExamples":[]},{"bab":14,"lesson":"tata-bahasa-bab-14-bentuk-plain","pattern":"〜なければなりません","notes":"Pola: bentuk ない, ganti ない dengan なければなりません. いく→いかない→いかなければなりません. Artinya harus melakukan, meskipun bentuknya mengandung unsur negatif. Jangan tertukar dengan てはいけません yang berarti dilarang melakukan.","dialog":"A: あした、がっこうへいかなければなりませんか。\nB: はい、いかなければなりません。","translation":"A: Apakah besok harus pergi ke sekolah?\nB: Ya, harus pergi.","addExamples":[]},{"bab":14,"lesson":"tata-bahasa-bab-14-bentuk-plain","pattern":"〜なくてもいいです","notes":"Pola: bentuk ない, ganti ない dengan なくてもいいです. はらわない→はらわなくてもいいです = tidak perlu membayar. Maknanya boleh tidak melakukan, bukan dilarang. Bentuk ini membebaskan kewajiban.","dialog":"A: あしたもしゅくだいをださなければなりませんか。\nB: いいえ、あしたはださなくてもいいです。","translation":"A: Apakah besok juga harus mengumpulkan PR?\nB: Tidak, besok tidak perlu mengumpulkannya.","addExamples":[]},{"bab":15,"lesson":"tata-bahasa-bab-15-bahasa-pelayanan","pattern":"〜を[counter]お願いします","notes":"Pola pesanan: benda を jumlah おねがいします. Contoh: コーヒーをふたつおねがいします. おねがいします adalah ungkapan sopan untuk meminta atau memesan. Untuk jumlah, gunakan kata bantu yang cocok. Ini bukan rumus untuk mengganti semua penggunaan ください.","dialog":"A: ごちゅうもんは？\nB: コーヒーをふたつおねがいします。","translation":"A: Pesan apa?\nB: Tolong dua kopi.","addExamples":[]},{"bab":15,"lesson":"tata-bahasa-bab-15-bahasa-pelayanan","pattern":"〜はいかがですか","notes":"Pola: benda は いかがですか. Dalam pelayanan, dipakai untuk menawarkan atau menyarankan sesuatu: おちゃはいかがですか. Jawaban menerima: おねがいします. Jawaban menolak dengan sopan: いいえ、けっこうです. いかが juga dapat menanyakan kesan dalam konteks lain.","dialog":"A: おちゃはいかがですか。\nB: はい、おねがいします。","translation":"A: Bagaimana kalau teh?\nB: Ya, boleh. Terima kasih.","addExamples":[]},{"bab":15,"lesson":"tata-bahasa-bab-15-bahasa-pelayanan","pattern":"〜になります (keigo)","notes":"Dalam menghitung harga, jumlah + になります berarti totalnya menjadi sekian: ぜんぶでせんえんになります. Pelajari sebagai ungkapan menyampaikan hasil perhitungan. Jangan menganggap になります pengganti です yang selalu lebih sopan. Untuk menunjuk barang atau kembalian, こちらがおつりです lebih sederhana dan jelas.","dialog":"A: ぜんぶでいくらですか。\nB: せんえんになります。","translation":"A: Semuanya berapa?\nB: Totalnya seribu yen.","addExamples":[],"replaceExamples":[["こちらが おつりに なります。","コーヒーふたつでろっぴゃくえんになります。","になります","Dua kopi totalnya enam ratus yen."]]},{"bab":15,"lesson":"tata-bahasa-bab-15-bahasa-pelayanan","pattern":"お〜ください","notes":"Pola umum: お + kata kerja bentuk ます tanpa ます + ください. まちます→おまちください = silakan tunggu. Pelajari sebagai ungkapan pelayanan yang lazim. Tidak semua kata kerja bisa diubah secara mekanis; ごりようください memakai ご, bukan お. Jangan menempelkan お pada kalimat てください.","dialog":"A: こちらでおまちください。\nB: はい。ありがとうございます。","translation":"A: Silakan tunggu di sini.\nB: Baik. Terima kasih.","addExamples":[]},{"bab":15,"lesson":"tata-bahasa-bab-15-memutuskan-perubahan","pattern":"〜にします","notes":"Pola: pilihan + にします. Dipakai saat memutuskan pilihan, misalnya コーヒーにします = saya pilih kopi. Bandingkan になります yang menyatakan perubahan/hasil. Kata sebelum に menunjukkan pilihan yang ditetapkan, bukan tempat kegiatan.","dialog":"A: なににしますか。\nB: おちゃにします。","translation":"A: Mau pilih apa?\nB: Saya pilih teh.","addExamples":[]},{"bab":15,"lesson":"tata-bahasa-bab-15-memutuskan-perubahan","pattern":"〜くなります／〜になります","notes":"Untuk perubahan: kata sifat い, ganti い→く + なります; kata sifat な tanpa な atau kata benda + になります. さむくなります = menjadi dingin; しずかになります = menjadi tenang; せんせいになります = menjadi guru. いい berubah menjadi よくなります. なりました menyatakan perubahan yang sudah terjadi.","dialog":"A: さむくなりましたね。\nB: そうですね。","translation":"A: Sudah menjadi dingin, ya?\nB: Ya, benar.","addExamples":[{"japanese":"へやがしずかになりました。","highlight":"しずかになりました","indonesian":"Ruangan menjadi tenang."}]},{"bab":16,"lesson":"tata-bahasa-bab-16-partikel-waktu-tanggal","pattern":"〜に[verb]","notes":"Gunakan に untuk waktu tertentu: jam, tanggal, bulan, tahun; nama hari juga dapat memakai に. ろくじにおきます = bangun pukul enam. Kata seperti きょう、あした、まいにち、いつ biasanya tanpa に. Jangan menyimpulkan semua keterangan waktu harus memakai に.","dialog":"A: なんじにおきますか。\nB: ろくじにおきます。","translation":"A: Anda bangun jam berapa?\nB: Saya bangun jam enam.","addExamples":[]},{"bab":16,"lesson":"tata-bahasa-bab-16-partikel-waktu-tanggal","pattern":"〜月〜日","notes":"Bulan memakai angka + がつ: しがつ (4), しちがつ (7), くがつ (9). Tanggal 1–10: ついたち、ふつか、みっか、よっか、いつか、むいか、なのか、ようか、ここのか、とおか. Perhatikan juga じゅうよっか (14), はつか (20), にじゅうよっか (24). Untuk kegiatan pada tanggal tertentu, tambahkan に setelah tanggal.","dialog":"A: たんじょうびはなんがつなんにちですか。\nB: しがつはつかです。","translation":"A: Ulang tahun Anda tanggal berapa?\nB: Tanggal 20 April.","addExamples":[{"japanese":"たんじょうびはしちがつはつかです。","highlight":"はつか","indonesian":"Ulang tahun saya tanggal 20 Juli."}]},{"bab":16,"lesson":"tata-bahasa-bab-16-frekuensi-bertanya-waktu","pattern":"何曜日／何月何日／いつ","notes":"なんようび menanyakan hari dalam minggu, なんがつなんにち menanyakan bulan dan tanggal, いつ menanyakan waktu secara umum. Jawaban harus sesuai jenis pertanyaan. いつ biasanya tanpa に; なんじに menanyakan jam terjadinya kegiatan.","dialog":"A: しけんはいつですか。\nB: げつようびです。\nA: なんじからですか。\nB: くじからです。","translation":"A: Kapan ujiannya?\nB: Hari Senin.\nA: Mulai jam berapa?\nB: Mulai pukul sembilan.","addExamples":[]},{"bab":16,"lesson":"tata-bahasa-bab-16-frekuensi-bertanya-waktu","pattern":"毎週／毎月／毎年","notes":"まいしゅう = setiap minggu; まいつき = setiap bulan; まいとし／まいねん = setiap tahun. Letakkan sebelum kegiatan dan jangan tambahkan に langsung setelah kata-kata ini. Untuk hari tertentu dalam siklus mingguan: まいしゅう、どようびに〜.","dialog":"A: まいしゅう、テニスをしますか。\nB: はい、どようびにします。","translation":"A: Apakah Anda bermain tenis setiap minggu?\nB: Ya, pada hari Sabtu.","addExamples":[]},{"bab":17,"lesson":"tata-bahasa-bab-17-suka-mahir","pattern":"〜が好きです／嫌いです","notes":"Ulasan Bab 7: orang は hal が すき／きらいです. すき adalah kesukaan, bukan kemampuan. きらい dapat terdengar kuat; あまりすきじゃありません lebih halus untuk tidak terlalu suka. Untuk membicarakan kegemaran, sebutkan benda atau kegiatan sebagai kata benda, misalnya おんがく atau りょうり.","dialog":"A: どんなたべものがすきですか。\nB: からいたべものがすきです。","translation":"A: Anda suka makanan seperti apa?\nB: Saya suka makanan pedas.","addExamples":[]},{"bab":17,"lesson":"tata-bahasa-bab-17-suka-mahir","pattern":"〜が上手です／下手です","notes":"Ulasan Bab 7: orang は hal が じょうず／へたです. Menilai tingkat kemahiran, bukan sekadar bisa atau tidak. できます pada kartu berikutnya menyatakan kemampuan. じょうず biasanya dipakai memuji orang lain; untuk diri sendiri, できます lebih netral daripada memuji diri sebagai じょうず.","dialog":"A: たなかさんはりょうりがじょうずですね。\nB: はい、とてもじょうずです。","translation":"A: Tanaka pandai memasak, ya?\nB: Ya, sangat pandai.","addExamples":[]},{"bab":17,"lesson":"tata-bahasa-bab-17-kemampuan-bertanya-jenis","pattern":"〜ができます","notes":"Pola: orang は keterampilan ができます. Pakai kata benda keterampilan, misalnya にほんご、りょうり、うんてん、ピアノ. Negatifnya できません. できます berarti mampu; じょうず berarti mahir. Jangan memasang kata kerja bentuk ます langsung sebelum ができます.","dialog":"A: ピアノができますか。\nB: はい、すこしできます。","translation":"A: Apakah Anda bisa bermain piano?\nB: Ya, bisa sedikit.","addExamples":[]},{"bab":17,"lesson":"tata-bahasa-bab-17-kemampuan-bertanya-jenis","pattern":"どんな〜","notes":"Pola: どんな + kata benda. Menanyakan jenis atau sifat: どんなほん = buku seperti apa. Jawab dengan jenis atau penjelasan, bukan hanya ya/tidak. Bedakan どのほん (buku yang mana dari pilihan yang ada) dan ほんはどうですか (bagaimana pendapat tentang buku itu).","dialog":"A: どんなほんをよみますか。\nB: にほんのりょうりのほんをよみます。","translation":"A: Anda membaca buku seperti apa?\nB: Saya membaca buku masakan Jepang.","addExamples":[]},{"bab":18,"lesson":"tata-bahasa-bab-18-membandingkan-dua-hal","pattern":"AはBより〜です","notes":"Pola: A は B より sifat です. A memiliki sifat itu lebih daripada B; B adalah pembanding. このほんはあのほんよりたかいです = buku ini lebih mahal daripada buku itu. Kata sifat tidak perlu diubah. Pastikan terjemahan tidak membalik A dan B.","dialog":"A: このほんはあのほんよりたかいですか。\nB: はい、このほんのほうがたかいです。","translation":"A: Apakah buku ini lebih mahal daripada buku itu?\nB: Ya, buku ini lebih mahal.","addExamples":[]},{"bab":18,"lesson":"tata-bahasa-bab-18-membandingkan-dua-hal","pattern":"AよりBのほうが〜","notes":"Pola: A より B のほうが sifat です. Yang lebih adalah B, yaitu kata sebelum のほうが. あかいかばんよりしろいかばんのほうがやすいです = tas putih lebih murah daripada tas merah. Bila pembandingnya sudah jelas, Aより bisa tidak disebutkan.","dialog":"A: あかいかばんとしろいかばんと、どちらがやすいですか。\nB: しろいかばんのほうがやすいです。","translation":"A: Mana yang lebih murah, tas merah atau tas putih?\nB: Tas putih lebih murah.","addExamples":[]},{"bab":18,"lesson":"tata-bahasa-bab-18-superlatif","pattern":"AとBとどちらが〜","notes":"Untuk membandingkan dua pilihan: A と B と どちらが sifat ですか. Jawaban: pilihan のほうが sifat です. Jika sama-sama disukai, jawab どちらもすきです. Pertanyaan どちら pada bab ini meminta pilihan, bukan arah/tempat seperti Bab 8.","dialog":"A: コーヒーとおちゃと、どちらがすきですか。\nB: おちゃのほうがすきです。","translation":"A: Mana yang lebih Anda sukai, kopi atau teh?\nB: Saya lebih suka teh.","addExamples":[]},{"bab":18,"lesson":"tata-bahasa-bab-18-superlatif","pattern":"〜の中で〜が一番〜","notes":"Pola: kelompok のなかで pilihan が いちばん sifat です. Sebutkan batas kelompok supaya paling punya acuan, misalnya くだもののなかで. Untuk bertanya, pilih kata tanya yang sesuai: なに (apa), だれ (siapa), どこ (mana/tempat), atau どれ (pilihan yang ditunjuk).","dialog":"A: くだもののなかで、なにがいちばんすきですか。\nB: りんごがいちばんすきです。","translation":"A: Di antara buah-buahan, apa yang paling Anda sukai?\nB: Saya paling suka apel.","addExamples":[]},{"bab":19,"lesson":"tata-bahasa-bab-19-keinginan","pattern":"〜たいです","notes":"Dari kata kerja bentuk ます, buang ます dan tambah たいです: いきます→いきたいです. Biasanya menyatakan keinginan sendiri atau menanyakan keinginan lawan bicara. Jangan menyatakan keinginan orang ketiga sebagai fakta tanpa konteks. Objek pada pola ini dapat memakai を atau が.","dialog":"A: やすみに、どこへいきたいですか。\nB: にほんへいきたいです。","translation":"A: Saat libur, Anda ingin pergi ke mana?\nB: Saya ingin pergi ke Jepang.","addExamples":[]},{"bab":19,"lesson":"tata-bahasa-bab-19-keinginan","pattern":"〜たくないです","notes":"Bentuk negatif keinginan: dari たいです ganti たい dengan たくないです. たべたい→たべたくないです. Bedakan たべません (tidak makan) dengan たべたくないです (tidak ingin makan). たい berubah seperti kata sifat い.","dialog":"A: きょう、でかけたいですか。\nB: いいえ、でかけたくないです。","translation":"A: Apakah hari ini Anda ingin keluar?\nB: Tidak, saya tidak ingin keluar.","addExamples":[]},{"bab":19,"lesson":"tata-bahasa-bab-19-keinginan","pattern":"[noun]が欲しいです","notes":"Pola: benda が ほしいです. Untuk ingin memiliki/mendapat sesuatu: あたらしいかばんがほしいです. Keinginan melakukan tindakan memakai Vたいです, bukan Vほしいです. Pada pola dasar ini digunakan untuk keinginan sendiri atau pertanyaan kepada lawan bicara.","dialog":"A: いま、なにがほしいですか。\nB: あたらしいかばんがほしいです。","translation":"A: Sekarang Anda menginginkan apa?\nB: Saya ingin tas baru.","addExamples":[]},{"bab":19,"lesson":"tata-bahasa-bab-19-rencana-ajakan","pattern":"〜つもりです","notes":"Pola: kata kerja bentuk kamus + つもりです untuk niat melakukan; bentuk ない + つもりです untuk niat tidak melakukan. いくつもりです／いかないつもりです. Fokusnya keputusan atau niat pribadi. Jangan memakai いきますつもりです.","dialog":"A: あした、なにをするつもりですか。\nB: うちでべんきょうするつもりです。","translation":"A: Besok Anda berniat melakukan apa?\nB: Saya berniat belajar di rumah.","addExamples":[],"meaning":"Menyatakan niat pribadi untuk melakukan sesuatu."},{"bab":19,"lesson":"tata-bahasa-bab-19-rencana-ajakan","pattern":"〜予定です","notes":"Pola: kata kerja bentuk kamus + よていです, atau kata benda kegiatan + のよていです. Menyatakan rencana/jadwal yang sudah diatur: しけんのよていです. Bedakan dari つもり yang menekankan niat pribadi. Keduanya belum berarti kegiatan sudah dilakukan.","dialog":"A: らいしゅう、せんせいとあうよていですか。\nB: はい、げつようびにあうよていです。","translation":"A: Apakah minggu depan Anda dijadwalkan bertemu guru?\nB: Ya, jadwalnya bertemu hari Senin.","addExamples":[],"meaning":"Menyatakan kegiatan yang sudah direncanakan atau dijadwalkan."},{"bab":19,"lesson":"tata-bahasa-bab-19-rencana-ajakan","pattern":"〜ましょう／ませんか","notes":"Ganti ます dengan ませんか untuk mengajak sambil menanyakan kesediaan. Ganti ます dengan ましょう untuk mengajak atau menyetujui ajakan. いっしょにたべませんか = mau makan bersama? Jawaban setuju: はい、たべましょう. Konteks membedakan ajakan ませんか dari pertanyaan negatif biasa.","dialog":"A: いっしょにひるごはんをたべませんか。\nB: いいですね。たべましょう。","translation":"A: Maukah Anda makan siang bersama?\nB: Ide bagus. Ayo makan.","addExamples":[]},{"bab":20,"lesson":"tata-bahasa-bab-20-pengalaman","pattern":"〜たことがあります","notes":"Pola: kata kerja bentuk た + ことがあります. Menyatakan pernah mengalami sesuatu sebelum sekarang, tanpa harus menyebut tanggal tertentu. いったことがあります = pernah pergi. Untuk menceritakan kejadian tertentu kemarin, gunakan きのういきました. Jangan memakai bentuk kamus sebelum こと pada pola pengalaman ini.","dialog":"A: にほんへいったことがありますか。\nB: はい、いちどあります。","translation":"A: Apakah Anda pernah pergi ke Jepang?\nB: Ya, pernah sekali.","addExamples":[]},{"bab":20,"lesson":"tata-bahasa-bab-20-pengalaman","pattern":"〜たことがありません","notes":"Pola: kata kerja bentuk た + ことがありません. Artinya belum pernah mengalami kegiatan itu. Kata kerjanya tetap bentuk た, bukan bentuk negatif: たべたことがありません. いちども dapat ditambahkan untuk menegaskan belum pernah sekali pun. Bedakan dengan きのうたべませんでした yang hanya menyatakan kemarin tidak makan.","dialog":"A: すしをたべたことがありますか。\nB: いいえ、まだたべたことがありません。","translation":"A: Apakah Anda pernah makan sushi?\nB: Belum, saya belum pernah memakannya.","addExamples":[]},{"bab":20,"lesson":"tata-bahasa-bab-20-penghubung-kalimat","pattern":"〜から (sebab)","notes":"Pola: alasan から、hasil/keputusan. から berada setelah alasan. Bentuk sopan dapat langsung dipakai: あめですから. Pada bentuk biasa, kata benda/kata sifat な memakai だ: あめだから、しずかだから. Kata kerja dan kata sifat い tidak ditambah だ: いくから、やすいから. Ini berbeda dari tempat/waktu から yang berarti dari.","dialog":"A: どうして、きょうはでかけませんか。\nB: あめですから。","translation":"A: Mengapa hari ini Anda tidak keluar?\nB: Karena hujan.","addExamples":[]},{"bab":20,"lesson":"tata-bahasa-bab-20-penghubung-kalimat","pattern":"〜が、〜","notes":"Pola: kalimat pertama が、kalimat kedua. が di sini berarti tetapi dan menghubungkan dua hal yang berlawanan. Pertahankan bentuk akhir kalimat pertama: たかいですが、べんりです. Bedakan が penghubung dengan が penanda subjek seperti ねこがいます.","dialog":"A: このかばんはどうですか。\nB: たかいですが、じょうぶです。","translation":"A: Bagaimana tas ini?\nB: Mahal, tetapi kuat.","addExamples":[],"replaceExamples":[["この 店は 高いですが、おいしいです。","このりょうりはたかいですが、おいしいです。","ですが","Masakan ini mahal, tetapi enak."]]},{"bab":20,"lesson":"tata-bahasa-bab-20-penghubung-kalimat","pattern":"そして／それから／でも","notes":"そして menambahkan informasi (dan/juga); それから menyebut kegiatan berikutnya (setelah itu); でも menyatakan pertentangan (tetapi). Ketiganya dapat mengawali kalimat baru. そして dan それから kadang sama-sama sesuai pada urutan kegiatan, jadi pilih berdasarkan hubungan makna, bukan hafalan bahwa hanya satu selalu benar.","dialog":"A: きのう、なにをしましたか。\nB: ほんをよみました。それから、てがみをかきました。","translation":"A: Kemarin Anda melakukan apa?\nB: Saya membaca buku. Setelah itu, saya menulis surat.","addExamples":[]}]$data$::jsonb;
 item JSONB; ex JSONB; g RECORD; found_count INT; gid UUID; next_order INT;
 scene JSONB; profiles JSONB; new_dialog TEXT; new_translation TEXT;
 speaker_a TEXT; speaker_b TEXT;
BEGIN
 SELECT jsonb_agg(jsonb_build_object('characterKey',s.character_key,
   'position',CASE WHEN s.character_key='anna-wijaya' THEN 'left' ELSE 'right' END,
   'speaker',CASE WHEN s.character_key='anna-wijaya' THEN 'A' ELSE 'B' END,
   'displayName',s.default_display_name,'voiceId',s.voice_id,'voiceName',s.voice_name,
   'profileVersion',s.profile_version,'custom',false) ORDER BY s.character_key)
 INTO profiles FROM dialogue_speakers s
 WHERE s.character_key IN ('anna-wijaya','hadi-pratama') AND coalesce(s.voice_id,'')<>'';

 FOR item IN SELECT value FROM jsonb_array_elements(plan) LOOP
   SELECT count(*),(array_agg(mg.id))[1] INTO found_count,gid
   FROM module_grammar mg JOIN lessons l ON l.id=mg.lesson_id
   JOIN modules m ON m.id=l.module_id JOIN courses c ON c.id=m.course_id
   WHERE c.slug='n5' AND l.slug=item->>'lesson' AND mg.pattern=item->>'pattern';
   IF found_count<>1 THEN
     RAISE EXCEPTION '176: missing/ambiguous teaching card % / %',item->>'lesson',item->>'pattern';
   END IF;
   SELECT * INTO STRICT g FROM module_grammar WHERE id=gid FOR UPDATE;
   -- A deliberate re-run never overwrites later teacher edits.
   IF EXISTS(SELECT 1 FROM n5_bunpou_content_backup_176 WHERE grammar_id=gid) THEN CONTINUE; END IF;
   INSERT INTO n5_bunpou_content_backup_176(grammar_id,before_grammar,before_examples)
   SELECT gid,to_jsonb(g),coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.sort_order,e.id)
     FILTER(WHERE e.id IS NOT NULL),'[]'::jsonb) FROM grammar_examples e WHERE e.grammar_id=gid;

   UPDATE module_grammar SET notes=item->>'notes',meaning=coalesce(item->>'meaning',meaning),updated_at=now() WHERE id=gid;
   FOR ex IN SELECT value FROM jsonb_array_elements(coalesce(item->'replaceExamples','[]')) LOOP
     UPDATE grammar_examples SET japanese=ex->>1,highlight=ex->>2,indonesian=ex->>3,updated_at=now()
       WHERE grammar_id=gid AND japanese=ex->>0;
     -- Keep the legacy single-example fallback in sync only when it matches.
     UPDATE module_grammar SET example=ex->>1 WHERE id=gid AND example=ex->>0;
   END LOOP;
   FOR ex IN SELECT value FROM jsonb_array_elements(coalesce(item->'translateExamples','[]')) LOOP
     UPDATE grammar_examples SET indonesian=ex->>1,updated_at=now()
       WHERE grammar_id=gid AND japanese=ex->>0 AND nullif(trim(indonesian),'') IS NULL;
     IF NOT EXISTS(SELECT 1 FROM grammar_examples WHERE grammar_id=gid AND japanese=ex->>0)
       AND g.example=ex->>0 THEN
       INSERT INTO grammar_examples(grammar_id,japanese,indonesian,sort_order) VALUES(gid,ex->>0,ex->>1,0);
     END IF;
   END LOOP;
   SELECT coalesce(max(sort_order),-1)+1 INTO next_order FROM grammar_examples WHERE grammar_id=gid;
   FOR ex IN SELECT value FROM jsonb_array_elements(item->'addExamples') LOOP
     IF NOT EXISTS(SELECT 1 FROM grammar_examples WHERE grammar_id=gid AND japanese=ex->>'japanese') THEN
       INSERT INTO grammar_examples(grammar_id,japanese,highlight,indonesian,sort_order)
         VALUES(gid,ex->>'japanese',ex->>'highlight',ex->>'indonesian',next_order);
       next_order:=next_order+1;
     END IF;
   END LOOP;
   IF nullif(trim(g.example_dialog),'') IS NULL OR coalesce((item->>'replaceDialog')::boolean,false) THEN
     scene:=g.dialog_scene;
     -- Keep custom per-character voices, labels, positions and profile versions.
     -- New dialogues use the configured character profiles, never invented IDs.
     IF scene IS NULL AND jsonb_array_length(profiles)=2 THEN
       scene:=jsonb_build_object('schemaVersion',1,'enabled',true,'backgroundKey','classroom','participants',profiles);
     END IF;
     speaker_a:=coalesce((SELECT p->>'speaker' FROM jsonb_array_elements(scene->'participants') p WHERE p->>'position'='left'),'A');
     speaker_b:=coalesce((SELECT p->>'speaker' FROM jsonb_array_elements(scene->'participants') p WHERE p->>'position'='right'),'B');
     -- Replace only line prefixes, without chained replacements or changing speech.
     SELECT string_agg(CASE left(line,2) WHEN 'A:' THEN speaker_a||substr(line,2)
       WHEN 'B:' THEN speaker_b||substr(line,2) ELSE line END,E'
' ORDER BY ord)
       INTO new_dialog FROM unnest(string_to_array(item->>'dialog',E'
')) WITH ORDINALITY t(line,ord);
     SELECT string_agg(CASE left(line,2) WHEN 'A:' THEN speaker_a||substr(line,2)
       WHEN 'B:' THEN speaker_b||substr(line,2) ELSE line END,E'
' ORDER BY ord)
       INTO new_translation FROM unnest(string_to_array(item->>'translation',E'
')) WITH ORDINALITY t(line,ord);
     UPDATE module_grammar SET example_dialog=new_dialog,example_dialog_id=new_translation,
       dialog_scene=scene,dialog_furigana=NULL WHERE id=gid;
   END IF;
   FOR ex IN SELECT value FROM jsonb_array_elements(coalesce(item->'dialogReplacements','[]')) LOOP
     IF position(ex->>0 IN g.example_dialog)>0 THEN
       UPDATE module_grammar SET example_dialog=replace(example_dialog,ex->>0,ex->>1),dialog_furigana=NULL WHERE id=gid;
     END IF;
   END LOOP;
   FOR ex IN SELECT value FROM jsonb_array_elements(coalesce(item->'translationReplacements','[]')) LOOP
     UPDATE module_grammar SET example_dialog_id=replace(example_dialog_id,ex->>0,ex->>1) WHERE id=gid;
   END LOOP;
   -- Existing question/companion fingerprints naturally become stale when their
   -- source changes. Never forge publication readiness or regrade frozen answers.
   IF NOT EXISTS(SELECT 1 FROM grammar_examples WHERE grammar_id=gid)
     AND nullif(trim(g.example),'') IS NULL THEN
     RAISE EXCEPTION '176: teaching card without examples %',gid;
   END IF;
   IF NOT EXISTS(SELECT 1 FROM module_grammar WHERE id=gid AND nullif(trim(example_dialog),'') IS NOT NULL) THEN
     RAISE EXCEPTION '176: teaching card without dialogue %',gid;
   END IF;
   UPDATE n5_bunpou_content_backup_176 SET
     after_grammar=(SELECT to_jsonb(mg) FROM module_grammar mg WHERE id=gid),
     after_examples=(SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.sort_order,e.id),'[]'::jsonb)
       FROM grammar_examples e WHERE grammar_id=gid) WHERE grammar_id=gid;
 END LOOP;
 RAISE NOTICE '176: completed % N5 teaching cards across 36 lessons',jsonb_array_length(plan);
END;
$complete$;
